<?php
require_once __DIR__.'/../config/app.php';require_admin();$q="SELECT claims.id claim_id,claims.message,claims.status claim_status,claims.created_at,items.id item_id,items.item_name,items.category,items.location,items.item_date,items.image,items.status item_status,claimant.full_name claimant_name,claimant.email claimant_email,reporter.full_name reporter_name FROM claims INNER JOIN items ON items.id=claims.item_id INNER JOIN users claimant ON claimant.id=claims.user_id INNER JOIN users reporter ON reporter.id=items.user_id ORDER BY CASE WHEN claims.status='pending' THEN 0 ELSE 1 END,claims.created_at DESC";$r=mysqli_query($conn,$q);$flash=get_flash();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Claims - UniFind</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><a class="brand" href="dashboard.php">UniFind Admin</a><div class="nav-actions"><a class="btn btn-small btn-secondary" href="dashboard.php">Dashboard</a><a class="btn btn-small" href="../logout.php">Logout</a></div></nav><main class="page-container"><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><section class="page-heading"><div><span class="eyebrow">Verification</span><h1>Claim Requests</h1><p>Review ownership details before approving a returned item.</p></div></section><?php if(mysqli_num_rows($r)):?><div class="claim-list"><?php while($c=mysqli_fetch_assoc($r)):?><article class="admin-claim-card"><?php if($c['image']&&is_file(__DIR__.'/../uploads/'.$c['image'])):?><img class="admin-claim-image" src="../uploads/<?=e($c['image'])?>" alt=""><?php else:?><div class="admin-claim-image placeholder">No Image</div><?php endif;?><div class="claim-row-body"><div class="card-topline"><h3><?=e($c['item_name'])?></h3><span class="status-pill <?=e($c['claim_status'])?>-pill"><?=strtoupper(e($c['claim_status']))?></span></div><div class="detail-list compact"><span><strong>Category:</strong> <?=e($c['category'])?></span><span><strong>Found at:</strong> <?=e($c['location'])?></span><span><strong>Found date:</strong> <?=e($c['item_date'])?></span><span><strong>Reported by:</strong> <?=e($c['reporter_name'])?></span><span><strong>Claimant:</strong> <?=e($c['claimant_name'])?> (<?=e($c['claimant_email'])?>)</span><span><strong>Submitted:</strong> <?=e($c['created_at'])?></span></div><div class="claim-message"><strong>Ownership details</strong><p><?=e($c['message'])?></p></div><?php if($c['claim_status']==='pending'):?><div class="button-row"><form method="post" action="update-claim.php"><input type="hidden" name="id" value="<?=(int)$c['claim_id']?>"><input type="hidden" name="action" value="approve"><button class="btn btn-success" onclick="return confirm('Approve this claim and mark the item returned?')">Approve</button></form><form method="post" action="update-claim.php"><input type="hidden" name="id" value="<?=(int)$c['claim_id']?>"><input type="hidden" name="action" value="reject"><button class="btn btn-danger" onclick="return confirm('Reject this claim?')">Reject</button></form></div><?php endif;?></div></article><?php endwhile;?></div><?php else:?><div class="empty-state"><h3>No claim requests</h3><p>No students have submitted ownership claims yet.</p></div><?php endif;?></main><script src="../js/ui-effects.js"></script></body></html>